use serde_json::{Value, json};

pub fn solve(input: Value) -> Value {
    if let Value::Array(rows) = input {
        let num_cols = rows[0].as_array().unwrap().len();
        let mut transposed = vec![vec![0; rows.len()]; num_cols];

        for (i, row) in rows.iter().enumerate() {
            if let Value::Array(row) = row {
                for (j, &val) in row.iter().enumerate() {
                    transposed[j][i] = val;
                }
            }
        }

        Value::Array(transposed)
    } else {
        json!(null)
    }
}
